     1→/**
     2→ * @file puppetc_agent.c
     3→ * @brief Puppet agent client
     4→ *
     5→ * Collects facts using libfacter_c, requests catalog from puppetc-server,
     6→ * and displays/applies the compiled catalog.
     7→ */
     8→
     9→#include <stdio.h>
    10→#include <stdlib.h>
    11→#include "puppet_memory.h"
    12→#include "color_output.h"
    13→#include "config_parser.h"
    14→#include <string.h>
    15→#include <stdbool.h>
    16→#include <getopt.h>
    17→#include <unistd.h>
    18→#include <curl/curl.h>
    19→
    20→#include "facter.h"
    21→#include "puppet_provider.h"
    22→#include "puppet_agent_ruby.h"
    23→#include "puppet_pluginsync.h"
    24→
    25→#define DEFAULT_SERVER "http://localhost:8140"
    26→#define DEFAULT_LIBDIR "/var/lib/puppetc/lib"
    27→#define DEFAULT_ENVIRONMENT "production"
    28→#define DEFAULT_CONFIG_FILE "/etc/puppetc/puppet.conf"
    29→#define AGENT_VERSION "0.1.0"
    30→
    31→/* Response buffer for curl */
    32→typedef struct {
    33→    char *data;
    34→    size_t size;
    35→} response_buffer_t;
    36→
    37→/* Agent configuration */
    38→typedef struct {
    39→    const char *server_url;
    40→    char *certname;
    41→    const char *environment;
    42→    const char *catalog_file;  /* Local catalog file to apply (for testing) */
    43→    const char *libdir;        /* Plugin library directory */
    44→    bool verbose;
    45→    bool noop;           /* No-op mode - don't apply changes */
    46→    bool apply_catalog;  /* Actually apply resources */
    47→    bool show_facts;     /* Just show facts, don't request catalog */
    48→    bool show_catalog;   /* Show catalog JSON */
    49→    bool use_ruby;       /* Enable Ruby support */
    50→    bool pluginsync;     /* Enable pluginsync */
    51→} agent_config_t;
    52→
    53→/* ============================================================================
    54→ * Helper Functions
    55→ * ============================================================================ */
    56→
    57→static size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    58→    size_t realsize = size * nmemb;
    59→    response_buffer_t *buf = (response_buffer_t *)userp;
    60→
    61→    char *ptr = puppet_realloc(buf->data, buf->size + realsize + 1);
    62→    if (!ptr) {
    63→        fprintf(stderr, "Error: Out of memory\n");
    64→        return 0;
    65→    }
    66→
    67→    buf->data = ptr;
    68→    memcpy(&(buf->data[buf->size]), contents, realsize);
    69→    buf->size += realsize;
    70→    buf->data[buf->size] = '\0';
    71→
    72→    return realsize;
    73→}
    74→
    75→static char *build_catalog_request(const char *certname, const char *environment,
    76→                                   facter_ctx_t *facts) {
    77→    /* Get facts as JSON */
    78→    char *facts_json = facter_to_json(facts);
    79→    if (!facts_json) {
    80→        return NULL;
    81→    }
    82→
    83→    /* Build request JSON
    84→     * Format: {"certname": "...", "environment": "...", "facts": {...}}
    85→     */
    86→    size_t buf_size = strlen(facts_json) + strlen(certname) + strlen(environment) + 256;
    87→    char *request = puppet_malloc(buf_size);
    88→    if (!request) {
    89→        puppet_free(facts_json);
    90→        return NULL;
    91→    }
    92→
    93→    snprintf(request, buf_size,
    94→             "{\n"
    95→             "  \"certname\": \"%s\",\n"
    96→             "  \"environment\": \"%s\",\n"
    97→             "  \"facts\": %s\n"
    98→             "}",
    99→             certname, environment, facts_json);
