     1→/**
     2→ * @file puppetc_server.c
     3→ * @brief HTTP server for Puppet catalog compilation
     4→ *
     5→ * Provides a REST API for compiling Puppet catalogs:
     6→ * - GET  /status           - Health check
     7→ * - POST /puppet/v4/catalog - Compile catalog for a node
     8→ */
     9→
    10→#include <stdio.h>
