    26→
    27→/* Default configuration */
    28→#define DEFAULT_PORT 8140
    29→#define DEFAULT_ENVIRONMENT "production"
    30→#define DEFAULT_CONFIG_FILE "/etc/puppetc/puppet.conf"
    31→
    32→/* Default PuppetDB path */
