    34→
    35→/* Global state */
    36→static volatile int running = 1;
    37→static char *manifest_path = NULL;
    38→static char *modules_path = NULL;
    39→static char *hiera_datadir = NULL;
    40→static char *puppetdb_path = NULL;
    41→static puppetdb_t *pdb = NULL;
    42→static int verbose = 0;
    43→
    44→/**
    45→ * @brief Signal handler for graceful shutdown
    46→ */
    47→static void signal_handler(int sig) {
    48→    (void)sig;
    49→    running = 0;
    50→}
    51→
    52→/**
    53→ * @brief Send a JSON response
    54→ */
    55→static enum MHD_Result send_json_response(struct MHD_Connection *connection,
    56→                                          unsigned int status_code,
    57→                                          const char *json) {
    58→    struct MHD_Response *response;
    59→    enum MHD_Result ret;
    60→
    61→    response = MHD_create_response_from_buffer(strlen(json),
    62→                                                (void *)json,
    63→                                                MHD_RESPMEM_MUST_COPY);
    64→    if (!response) return MHD_NO;
    65→
    66→    MHD_add_response_header(response, "Content-Type", "application/json");
    67→    MHD_add_response_header(response, "Access-Control-Allow-Origin", "*");
    68→
    69→    ret = MHD_queue_response(connection, status_code, response);
    70→    MHD_destroy_response(response);
    71→
    72→    return ret;
    73→}
    74→
    75→/**
    76→ * @brief Send an error response
    77→ */
    78→static enum MHD_Result send_error(struct MHD_Connection *connection,
    79→                                  unsigned int status_code,
    80→                                  const char *message) {
    81→    char json[512];
    82→    snprintf(json, sizeof(json),
    83→             "{\"error\": \"%s\", \"status\": %u}", message, status_code);
    84→    return send_json_response(connection, status_code, json);
    85→}
    86→
    87→/**
    88→ * @brief Handle GET /status
    89→ */
    90→static enum MHD_Result handle_status(struct MHD_Connection *connection) {
    91→    const char *json = "{\"status\": \"ok\", \"version\": \"0.0.1\"}";
    92→    return send_json_response(connection, MHD_HTTP_OK, json);
    93→}
