   123→/**
   124→ * @brief Compute MD5 checksum of a file
   125→ * @return Hex string (caller must free) or NULL on error
   126→ */
   127→static char *file_md5(const char *path) {
   128→    FILE *fp = fopen(path, "rb");
   129→    if (!fp) return NULL;
   130→
   131→    MD5_CTX ctx;
   132→    MD5_Init(&ctx);
   133→
   134→    unsigned char buf[8192];
   135→    size_t n;
   136→    while ((n = fread(buf, 1, sizeof(buf), fp)) > 0) {
   137→        MD5_Update(&ctx, buf, n);
   138→    }
   139→    fclose(fp);
   140→
   141→    unsigned char digest[MD5_DIGEST_LENGTH];
   142→    MD5_Final(digest, &ctx);
   143→
   144→    char *hex = puppet_malloc(MD5_DIGEST_LENGTH * 2 + 1);
   145→    if (!hex) return NULL;
   146→
   147→    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
   148→        snprintf(hex + i * 2, 3, "%02x", digest[i]);
   149→    }
   150→    return hex;
   151→}
