   153→/**
   154→ * @brief Recursively scan a directory for files
   155→ * @param base_path The base path (module's lib/)
   156→ * @param rel_path Relative path within lib/
   157→ * @param json_buf Buffer to append JSON to
   158→ * @param buf_size Buffer size
   159→ * @param buf_pos Current position in buffer
   160→ * @param first Pointer to first element flag
   161→ */
   162→static void scan_lib_directory(const char *base_path, const char *rel_path,
   163→                               char *json_buf, size_t buf_size, size_t *buf_pos,
   164→                               int *first) {
   165→    char full_path[4096];
   166→    if (rel_path && strlen(rel_path) > 0) {
   167→        snprintf(full_path, sizeof(full_path), "%s/%s", base_path, rel_path);
   168→    } else {
   169→        snprintf(full_path, sizeof(full_path), "%s", base_path);
   170→    }
   171→
   172→    DIR *dir = opendir(full_path);
   173→    if (!dir) return;
   174→
   175→    struct dirent *entry;
   176→    while ((entry = readdir(dir)) != NULL) {
   177→        if (entry->d_name[0] == '.') continue;  /* Skip . and .. and hidden */
   178→
   179→        char entry_path[4096];
   180→        snprintf(entry_path, sizeof(entry_path), "%s/%s", full_path, entry->d_name);
   181→
   182→        char entry_rel[4096];
   183→        if (rel_path && strlen(rel_path) > 0) {
   184→            snprintf(entry_rel, sizeof(entry_rel), "%s/%s", rel_path, entry->d_name);
   185→        } else {
   186→            snprintf(entry_rel, sizeof(entry_rel), "%s", entry->d_name);
   187→        }
   188→
   189→        struct stat st;
   190→        if (stat(entry_path, &st) != 0) continue;
   191→
   192→        if (S_ISDIR(st.st_mode)) {
   193→            /* Recurse into subdirectory */
   194→            scan_lib_directory(base_path, entry_rel, json_buf, buf_size, buf_pos, first);
   195→        } else if (S_ISREG(st.st_mode)) {
   196→            /* Add file entry */
   197→            char *checksum = file_md5(entry_path);
   198→            if (checksum) {
   199→                size_t needed = snprintf(NULL, 0,
   200→                    "%s{\"path\":\"%s\",\"checksum\":{\"type\":\"md5\",\"value\":\"{md5}%s\"},\"type\":\"file\"}",
   201→                    *first ? "" : ",", entry_rel, checksum);
   202→                if (*buf_pos + needed < buf_size - 1) {
   203→                    *buf_pos += sprintf(json_buf + *buf_pos,
   204→                        "%s{\"path\":\"%s\",\"checksum\":{\"type\":\"md5\",\"value\":\"{md5}%s\"},\"type\":\"file\"}",
   205→                        *first ? "" : ",", entry_rel, checksum);
   206→                    *first = 0;
   207→                }
   208→                puppet_free(checksum);
   209→            }
   210→        }
   211→    }
   212→    closedir(dir);
   213→}
