    32→/**
    33→ * @brief Trim leading and trailing whitespace in place
    34→ */
    35→static char *trim(char *str) {
    36→    if (!str) return NULL;
    37→
    38→    /* Trim leading whitespace */
    39→    while (isspace((unsigned char)*str)) str++;
    40→
    41→    if (*str == '\0') return str;
    42→
    43→    /* Trim trailing whitespace */
    44→    char *end = str + strlen(str) - 1;
    45→    while (end > str && isspace((unsigned char)*end)) end--;
    46→    end[1] = '\0';
    47→
    48→    return str;
    49→}
